import {
    useEffect, useId, useRef, useState,
    type ComponentProps, type FormEvent,
} from "react";
import { Badge, type BadgeProps } from "./badge";
import { Button } from "./button";
import { Input } from "./input";
import { NativeSelect } from "./native-select";
import { cn } from "./utils";

type WorkflowStatusCategory = "not-started" | "active" | "done";

type WorkflowStatusDefinition = {
    id: string;
    name: string;
    category: WorkflowStatusCategory;
    color: string;
    variant?: BadgeProps["variant"];
    allowedTransitions: readonly string[];
};

type WorkflowTaskReference = {
    id: string;
    title: string;
    statusId: string;
};

type WorkflowTaskStatusChange = {
    taskId: string;
    fromStatusId: string;
    toStatusId: string;
};

type WorkflowStatusMigration = {
    removedStatusId: string;
    replacementStatusId: string;
    taskStatusChanges: readonly WorkflowTaskStatusChange[];
};

type StatusWorkflowSaveRequest = {
    statuses: WorkflowStatusDefinition[];
    migrations: WorkflowStatusMigration[];
};

type StatusWorkflowEditorProps = Omit<
    ComponentProps<"section">,
    "children" | "aria-label"
> & {
    statuses: readonly WorkflowStatusDefinition[];
    tasks: readonly WorkflowTaskReference[];
    onSave: (
        request: StatusWorkflowSaveRequest,
    ) => void | Promise<void>;
    label?: string;
    readOnly?: boolean;
    saveErrorMessage?: string;
};

type StatusRemovalDraft = {
    statusId: string;
    replacementStatusId: string;
    taskTargets: Record<string, string>;
};

const statusCategories: readonly {
    value: WorkflowStatusCategory;
    label: string;
}[] = [
    { value: "not-started", label: "미시작" },
    { value: "active", label: "진행 중" },
    { value: "done", label: "완료" },
];

const badgeVariants: readonly {
    value: NonNullable<BadgeProps["variant"]>;
    label: string;
}[] = [
    { value: "default", label: "기본" },
    { value: "outline", label: "외곽선" },
    { value: "accent", label: "강조" },
    { value: "danger", label: "위험" },
];

function cloneStatuses(
    statuses: readonly WorkflowStatusDefinition[],
) {
    return statuses.map((status) => ({
        ...status,
        allowedTransitions: [...status.allowedTransitions],
    }));
}

function validateWorkflow(
    statuses: readonly WorkflowStatusDefinition[],
    tasks: readonly WorkflowTaskReference[],
    allowEmptyDraftNames = false,
) {
    const statusIds = new Set<string>();
    for (const status of statuses) {
        if (!status.id.trim() ||
            (!allowEmptyDraftNames && !status.name.trim())) {
            throw new Error("StatusWorkflowEditor statuses need IDs and names.");
        }
        if (!/^#[0-9a-f]{6}$/i.test(status.color)) {
            throw new Error(
                `StatusWorkflowEditor color must be a hex value: ${status.id}`,
            );
        }
        if (statusIds.has(status.id)) {
            throw new Error(
                `StatusWorkflowEditor status ID is duplicated: ${status.id}`,
            );
        }
        if (!statusCategories.some((category) =>
            category.value === status.category,
        )) {
            throw new RangeError(
                `StatusWorkflowEditor category is not supported: ${status.category}`,
            );
        }
        if (status.variant !== undefined && !badgeVariants.some((variant) =>
            variant.value === status.variant,
        )) {
            throw new RangeError(
                `StatusWorkflowEditor variant is not supported: ${status.variant}`,
            );
        }
        const transitionIds = new Set<string>();
        for (const targetId of status.allowedTransitions) {
            if (!targetId.trim() || transitionIds.has(targetId)) {
                throw new Error(
                    `StatusWorkflowEditor transitions need unique IDs: ${status.id}`,
                );
            }
            transitionIds.add(targetId);
        }
        statusIds.add(status.id);
    }

    const taskIds = new Set<string>();
    for (const task of tasks) {
        if (!task.id.trim() || !task.title.trim() || !task.statusId.trim()) {
            throw new Error(
                "StatusWorkflowEditor tasks need IDs, titles and status IDs.",
            );
        }
        if (taskIds.has(task.id)) {
            throw new Error(
                `StatusWorkflowEditor task ID is duplicated: ${task.id}`,
            );
        }
        taskIds.add(task.id);
    }
}

function StatusWorkflowEditor({
    statuses,
    tasks,
    onSave,
    label = "상태 흐름",
    readOnly = false,
    saveErrorMessage = "상태 흐름을 저장하지 못했습니다. 변경 내용은 보존했습니다.",
    className,
    ...props
}: StatusWorkflowEditorProps) {
    const generatedId = useId();
    const sourceStatuses = useRef(statuses);
    const savePending = useRef(false);
    const [draftStatuses, setDraftStatuses] = useState<WorkflowStatusDefinition[]>(() =>
        cloneStatuses(statuses),
    );
    const [migrations, setMigrations] = useState<WorkflowStatusMigration[]>([]);
    const [dirty, setDirty] = useState(false);
    const dirtyRef = useRef(false);
    const [savePendingState, setSavePendingState] = useState(false);
    const [saveError, setSaveError] = useState<string | null>(null);
    const [removalDraft, setRemovalDraft] =
        useState<StatusRemovalDraft | null>(null);
    const [removalError, setRemovalError] = useState<string | null>(null);
    const [newStatusId, setNewStatusId] = useState("");
    const [newStatusName, setNewStatusName] = useState("");
    const [newStatusCategory, setNewStatusCategory] =
        useState<WorkflowStatusCategory>("not-started");
    const [newStatusColor, setNewStatusColor] = useState("#64748b");
    const [newStatusError, setNewStatusError] = useState<string | null>(null);

    validateWorkflow(statuses, tasks);
    validateWorkflow(draftStatuses, tasks, true);

    useEffect(() => {
        if (sourceStatuses.current === statuses) return;
        sourceStatuses.current = statuses;
        if (dirtyRef.current) return;
        setDraftStatuses(cloneStatuses(statuses));
        setMigrations([]);
    }, [statuses]);

    function markDirty() {
        dirtyRef.current = true;
        setDirty(true);
        setSaveError(null);
    }

    function setStatusesAndMarkDirty(
        update: (
            current: WorkflowStatusDefinition[],
        ) => WorkflowStatusDefinition[],
    ) {
        setDraftStatuses((current) => update(current));
        markDirty();
    }

    function updateStatus(
        statusId: string,
        update: (status: WorkflowStatusDefinition) => WorkflowStatusDefinition,
    ) {
        setStatusesAndMarkDirty((current) => current.map((status) =>
            status.id === statusId ? update(status) : status,
        ));
    }

    function removeStatusFromDraft(statusId: string) {
        setStatusesAndMarkDirty((current) => current
            .filter((status) => status.id !== statusId)
            .map((status) => ({
                ...status,
                allowedTransitions: status.allowedTransitions.filter(
                    (targetId) => targetId !== statusId,
                ),
            })));
    }

    function changeOrder(statusId: string, direction: -1 | 1) {
        setStatusesAndMarkDirty((current) => {
            const index = current.findIndex((status) => status.id === statusId);
            const target = index + direction;
            if (index < 0 || target < 0 || target >= current.length) {
                return current;
            }
            const next = [...current];
            [next[index], next[target]] = [next[target], next[index]];
            return next;
        });
    }

    function addStatus(event: FormEvent<HTMLFormElement>) {
        event.preventDefault();
        const id = newStatusId.trim();
        const name = newStatusName.trim();
        if (!id || !name) {
            setNewStatusError("상태 ID와 이름을 입력하세요.");
            return;
        }
        if (draftStatuses.some((status) => status.id === id)) {
            setNewStatusError("이미 사용 중인 상태 ID입니다.");
            return;
        }
        setDraftStatuses((current) => [...current, {
            id,
            name,
            category: newStatusCategory,
            color: newStatusColor,
            variant: "default",
            allowedTransitions: [],
        }]);
        setNewStatusId("");
        setNewStatusName("");
        setNewStatusCategory("not-started");
        setNewStatusColor("#64748b");
        setNewStatusError(null);
        markDirty();
    }

    function toggleTransition(
        statusId: string,
        targetStatusId: string,
        enabled: boolean,
    ) {
        updateStatus(statusId, (status) => ({
            ...status,
            allowedTransitions: enabled
                ? [...status.allowedTransitions, targetStatusId]
                : status.allowedTransitions.filter((id) =>
                    id !== targetStatusId,
                ),
        }));
    }

    function beginRemoval(statusId: string) {
        const affectedTasks = tasks.filter((task) => task.statusId === statusId);
        if (!affectedTasks.length) {
            removeStatusFromDraft(statusId);
            return;
        }
        setRemovalDraft({
            statusId,
            replacementStatusId: "",
            taskTargets: {},
        });
        setRemovalError(null);
    }

    function confirmRemoval() {
        if (!removalDraft) return;
        const removedStatus = draftStatuses.find((status) =>
            status.id === removalDraft.statusId,
        );
        const replacementExists = draftStatuses.some((status) =>
            status.id === removalDraft.replacementStatusId &&
            status.id !== removalDraft.statusId,
        );
        const affectedTasks = tasks.filter((task) =>
            task.statusId === removalDraft.statusId,
        );
        if (!removedStatus || !replacementExists ||
            affectedTasks.some((task) => !draftStatuses.some((status) =>
                status.id === removalDraft.taskTargets[task.id] &&
                status.id !== removalDraft.statusId,
            ))) {
            setRemovalError("대체 상태와 각 Task의 이동 상태를 선택하세요.");
            return;
        }

        const migration: WorkflowStatusMigration = {
            removedStatusId: removedStatus.id,
            replacementStatusId: removalDraft.replacementStatusId,
            taskStatusChanges: affectedTasks.map((task) => ({
                taskId: task.id,
                fromStatusId: task.statusId,
                toStatusId: removalDraft.taskTargets[task.id],
            })),
        };
        setMigrations((current) => [...current, migration]);
        removeStatusFromDraft(removedStatus.id);
        setRemovalDraft(null);
        setRemovalError(null);
    }

    function isMigrationTarget(statusId: string) {
        return migrations.some((migration) =>
            migration.replacementStatusId === statusId ||
            migration.taskStatusChanges.some((change) =>
                change.toStatusId === statusId,
            ),
        );
    }

    async function saveWorkflow() {
        if (readOnly || savePending.current || !dirty || removalDraft) return;
        try {
            validateWorkflow(draftStatuses, tasks);
        } catch {
            setSaveError("각 상태에 고유 ID와 이름이 필요합니다.");
            return;
        }
        const request: StatusWorkflowSaveRequest = {
            statuses: cloneStatuses(draftStatuses),
            migrations: migrations.map((migration) => ({
                ...migration,
                taskStatusChanges: migration.taskStatusChanges.map((change) => ({
                    ...change,
                })),
            })),
        };
        savePending.current = true;
        setSavePendingState(true);
        setSaveError(null);
        try {
            await onSave(request);
            dirtyRef.current = false;
            setDirty(false);
            setMigrations([]);
        } catch {
            setSaveError(saveErrorMessage);
        } finally {
            savePending.current = false;
            setSavePendingState(false);
        }
    }

    const statusIds = new Set(draftStatuses.map((status) => status.id));
    const tasksByStatus = new Map<string, WorkflowTaskReference[]>();
    for (const task of tasks) {
        if (!statusIds.has(task.statusId)) continue;
        const affected = tasksByStatus.get(task.statusId) ?? [];
        affected.push(task);
        tasksByStatus.set(task.statusId, affected);
    }
    const unknownStatusTasks = tasks.filter((task) =>
        !statusIds.has(task.statusId) && !migrations.some((migration) =>
            migration.removedStatusId === task.statusId &&
            migration.taskStatusChanges.some((change) =>
                change.taskId === task.id,
            ),
        ),
    );
    const removalStatus = removalDraft && draftStatuses.find((status) =>
        status.id === removalDraft.statusId,
    );
    const removalTasks = removalDraft
        ? tasks.filter((task) => task.statusId === removalDraft.statusId)
        : [];
    const canConfirmRemoval = !!removalDraft &&
        !!removalDraft.replacementStatusId &&
        draftStatuses.some((status) =>
            status.id === removalDraft.replacementStatusId &&
            status.id !== removalDraft.statusId,
        ) &&
        removalTasks.every((task) =>
            draftStatuses.some((status) =>
                status.id === removalDraft.taskTargets[task.id] &&
                status.id !== removalDraft.statusId,
            ),
        );

    return (
        <section {...props} aria-label={label}
            className={cn("@container grid min-w-0 gap-4", className)}>
            <header className="flex min-w-0 flex-wrap items-baseline justify-between gap-3">
                <h2 className="m-0 text-base font-semibold text-foreground">
                    {label}
                </h2>
                <Button type="button" variant="outline"
                    disabled={readOnly || savePendingState || !dirty ||
                        !!removalDraft}
                    onClick={() => void saveWorkflow()}>
                    {savePendingState ? "저장 중…" : "변경 사항 저장"}
                </Button>
            </header>
            <ol aria-label={`${label} 순서`}
                className="m-0 grid list-none gap-3 p-0">
                {draftStatuses.map((status, index) => {
                    const usedTasks = tasksByStatus.get(status.id) ?? [];
                    const knownTransitions = status.allowedTransitions.filter(
                        (targetId) => statusIds.has(targetId),
                    );
                    const unknownTransitions = status.allowedTransitions.filter(
                        (targetId) => !statusIds.has(targetId),
                    );
                    const statusDisabled = readOnly || savePendingState ||
                        !!removalDraft;
                    return (
                        <li key={status.id} data-status-id={status.id}
                            className={
                                "grid min-w-0 gap-3 rounded-sm border " +
                                "border-border bg-surface p-[var(--space-3)]"
                            }>
                            <div className="flex min-w-0 flex-wrap items-center gap-3">
                                <span className="shrink-0 text-xs text-muted">
                                    {index + 1}.
                                </span>
                                <span className="min-w-0 flex-1">
                                    <span className="inline-flex min-w-0 items-center gap-2">
                                        <span aria-hidden="true"
                                            className="size-3 shrink-0 rounded-full border border-border"
                                            style={{ backgroundColor: status.color }} />
                                        <Badge variant={status.variant ?? "default"}>
                                            {status.name}
                                        </Badge>
                                    </span>
                                </span>
                                <span className="text-xs text-muted">#{status.id}</span>
                                <span className="text-xs text-muted">
                                    {usedTasks.length}개 Task
                                </span>
                            </div>
                            <div className="grid min-w-0 gap-3 @md:grid-cols-2">
                                <div className="grid min-w-0 gap-1">
                                    <label className="text-xs text-muted"
                                        htmlFor={`${generatedId}-${encodeURIComponent(status.id)}-name`}>
                                        상태 이름
                                    </label>
                                    <Input
                                        id={`${generatedId}-${encodeURIComponent(status.id)}-name`}
                                        aria-label={`${status.name} 이름`}
                                        value={status.name}
                                        disabled={statusDisabled}
                                        onChange={(event) => {
                                            const name = event.currentTarget.value;
                                            updateStatus(status.id, (current) => ({
                                                ...current,
                                                name,
                                            }));
                                        }} />
                                </div>
                                <div className="grid min-w-0 gap-1">
                                    <label className="text-xs text-muted"
                                        htmlFor={`${generatedId}-${encodeURIComponent(status.id)}-category`}>
                                        분류
                                    </label>
                                    <NativeSelect
                                        id={`${generatedId}-${encodeURIComponent(status.id)}-category`}
                                        aria-label={`${status.name} 분류`}
                                        value={status.category}
                                        disabled={statusDisabled}
                                        onChange={(event) => {
                                            const category = event.currentTarget.value as WorkflowStatusCategory;
                                            updateStatus(status.id, (current) => ({
                                                ...current,
                                                category,
                                            }));
                                        }}>
                                        {statusCategories.map((category) => (
                                            <option key={category.value}
                                                value={category.value}>
                                                {category.label}
                                            </option>
                                        ))}
                                    </NativeSelect>
                                </div>
                                <div className="grid min-w-0 gap-1 @md:col-span-2">
                                    <label className="text-xs text-muted"
                                        htmlFor={`${generatedId}-${encodeURIComponent(status.id)}-color`}>
                                        상태 색상
                                    </label>
                                    <Input
                                        id={`${generatedId}-${encodeURIComponent(status.id)}-color`}
                                        aria-label={`${status.name} 색상`}
                                        type="color"
                                        value={status.color}
                                        disabled={statusDisabled}
                                        onChange={(event) => {
                                            const color = event.currentTarget.value;
                                            updateStatus(status.id, (current) => ({
                                                ...current,
                                                color,
                                            }));
                                        }} />
                                </div>
                                <div className="grid min-w-0 gap-1 @md:col-span-2">
                                    <label className="text-xs text-muted"
                                        htmlFor={`${generatedId}-${encodeURIComponent(status.id)}-variant`}>
                                        Badge 표현
                                    </label>
                                    <NativeSelect
                                        id={`${generatedId}-${encodeURIComponent(status.id)}-variant`}
                                        aria-label={`${status.name} Badge 표현`}
                                        value={status.variant ?? "default"}
                                        disabled={statusDisabled}
                                        onChange={(event) => {
                                            const variant = event.currentTarget.value as BadgeProps["variant"];
                                            updateStatus(status.id, (current) => ({
                                                ...current,
                                                variant,
                                            }));
                                        }}>
                                        {badgeVariants.map((variant) => (
                                            <option key={variant.value}
                                                value={variant.value}>
                                                {variant.label}
                                            </option>
                                        ))}
                                    </NativeSelect>
                                </div>
                            </div>
                            <fieldset className="grid min-w-0 gap-2 border-0 p-0">
                                <legend className="mb-2 text-sm font-medium">
                                    허용 전환
                                </legend>
                                {draftStatuses.length === 0 ? (
                                    <p className="m-0 text-sm text-muted">
                                        상태를 추가한 뒤 전환을 설정하세요.
                                    </p>
                                ) : (
                                    <ul className="m-0 grid list-none gap-2 p-0 @md:grid-cols-2">
                                        {draftStatuses.map((target) => (
                                            <li key={target.id}>
                                                <label className="inline-flex min-w-0 items-center gap-2 text-sm">
                                                    <input type="checkbox"
                                                        checked={knownTransitions.includes(target.id)}
                                                        disabled={statusDisabled}
                                                        onChange={(event) => toggleTransition(
                                                            status.id,
                                                            target.id,
                                                            event.currentTarget.checked,
                                                        )}
                                                        className="size-4 accent-[var(--accent)]" />
                                                    <span className="min-w-0 break-words">
                                                        {target.name}
                                                    </span>
                                                </label>
                                            </li>
                                        ))}
                                    </ul>
                                )}
                                {unknownTransitions.length > 0 && (
                                    <ul aria-label={`${status.name} 알 수 없는 전환`}
                                        className="m-0 grid list-none gap-2 p-0">
                                        {unknownTransitions.map((targetId) => (
                                            <li key={targetId}
                                                className="flex min-w-0 flex-wrap items-center gap-2">
                                                <span className="min-w-0 text-sm text-muted">
                                                    알 수 없는 전환 대상 ({targetId})
                                                </span>
                                                <Button type="button" variant="ghost"
                                                    aria-label={`${status.name} 알 수 없는 전환 ${targetId} 제거`}
                                                    disabled={statusDisabled}
                                                    onClick={() => toggleTransition(
                                                        status.id,
                                                        targetId,
                                                        false,
                                                    )}>
                                                    제거
                                                </Button>
                                            </li>
                                        ))}
                                    </ul>
                                )}
                            </fieldset>
                            <div role="group"
                                aria-label={`${status.name} 순서와 삭제`}
                                className="flex flex-wrap gap-2">
                                <Button type="button" variant="outline"
                                    aria-label={`${status.name} 위로 이동`}
                                    disabled={statusDisabled || index === 0}
                                    onClick={() => changeOrder(status.id, -1)}>
                                    위로 이동
                                </Button>
                                <Button type="button" variant="outline"
                                    aria-label={`${status.name} 아래로 이동`}
                                    disabled={statusDisabled ||
                                        index === draftStatuses.length - 1}
                                    onClick={() => changeOrder(status.id, 1)}>
                                    아래로 이동
                                </Button>
                                <Button type="button" variant="ghost"
                                    aria-label={`${status.name} 삭제`}
                                    disabled={statusDisabled || isMigrationTarget(status.id)}
                                    onClick={() => beginRemoval(status.id)}>
                                    상태 삭제
                                </Button>
                                {isMigrationTarget(status.id) && (
                                    <span className="self-center text-xs text-muted">
                                        미저장 Task 이동 대상이라 삭제할 수 없습니다.
                                    </span>
                                )}
                            </div>
                        </li>
                    );
                })}
            </ol>
            {draftStatuses.length === 0 && (
                <p className="m-0 text-sm text-muted">
                    상태를 하나 이상 추가하세요.
                </p>
            )}
            {removalDraft && removalStatus && (
                <section aria-label={`${removalStatus.name} 삭제와 Task 이동`}
                    className="grid min-w-0 gap-3 rounded-sm border border-border bg-surface-subtle p-[var(--space-3)]">
                    <h3 className="m-0 text-sm font-semibold text-foreground">
                        {removalStatus.name} 상태 삭제와 Task 이동
                    </h3>
                    <p className="m-0 text-sm text-muted">
                        상태를 삭제하려면 대체 상태와 영향을 받는 각 Task의 이동 상태를 선택하세요.
                    </p>
                    <label className="grid min-w-0 gap-1">
                        <span className="text-xs text-muted">대체 상태</span>
                        <NativeSelect aria-label="삭제할 상태의 대체 상태"
                            value={removalDraft.replacementStatusId}
                            disabled={readOnly || savePendingState}
                            onChange={(event) => {
                                const replacementStatusId = event.currentTarget.value;
                                setRemovalDraft((current) => current ? ({
                                    ...current,
                                    replacementStatusId,
                                    taskTargets: {},
                                }) : current);
                                setRemovalError(null);
                            }}>
                            <option value="">상태 선택</option>
                            {draftStatuses.filter((status) =>
                                status.id !== removalDraft.statusId,
                            ).map((status) => (
                                <option key={status.id} value={status.id}>
                                    {status.name}
                                </option>
                            ))}
                        </NativeSelect>
                    </label>
                    {removalTasks.length > 0 && (
                        <ul aria-label="이동할 Task 목록"
                            className="m-0 grid list-none gap-3 p-0">
                            {removalTasks.map((task) => (
                                <li key={task.id}
                                    className="grid min-w-0 gap-1">
                                    <label className="text-xs text-muted">
                                        {task.title} (#{task.id}) 이동 대상
                                        <NativeSelect
                                            aria-label={`${task.title} 상태 이동 대상`}
                                            value={removalDraft.taskTargets[task.id] ?? ""}
                                            disabled={readOnly || savePendingState ||
                                                !removalDraft.replacementStatusId}
                                            onChange={(event) => {
                                                const targetId = event.currentTarget.value;
                                                setRemovalDraft((current) => current ? ({
                                                    ...current,
                                                    taskTargets: {
                                                        ...current.taskTargets,
                                                        [task.id]: targetId,
                                                    },
                                                }) : current);
                                                setRemovalError(null);
                                            }}>
                                            <option value="">상태 선택</option>
                                            {draftStatuses.filter((status) =>
                                                status.id !== removalDraft.statusId,
                                            ).map((status) => (
                                                <option key={status.id}
                                                    value={status.id}>
                                                    {status.name}
                                                </option>
                                            ))}
                                        </NativeSelect>
                                    </label>
                                </li>
                            ))}
                        </ul>
                    )}
                    {removalError && (
                        <p role="alert" className="m-0 text-sm text-danger">
                            {removalError}
                        </p>
                    )}
                    <div className="flex flex-wrap gap-2">
                        <Button type="button" variant="outline"
                            disabled={readOnly || savePendingState ||
                                !canConfirmRemoval}
                            onClick={confirmRemoval}>
                            {removalTasks.length}개 Task 이동 후 상태 삭제
                        </Button>
                        <Button type="button" variant="ghost"
                            disabled={readOnly || savePendingState}
                            onClick={() => {
                                setRemovalDraft(null);
                                setRemovalError(null);
                            }}>
                            취소
                        </Button>
                    </div>
                </section>
            )}
            {unknownStatusTasks.length > 0 && (
                <div aria-label="알 수 없는 상태를 가진 Task"
                    className="grid min-w-0 gap-2 rounded-sm border border-border p-[var(--space-3)]">
                    <h3 className="m-0 text-sm font-medium">
                        알 수 없는 상태를 가진 Task
                    </h3>
                    <ul className="m-0 grid list-none gap-1 p-0">
                        {unknownStatusTasks.map((task) => (
                            <li key={task.id}
                                className="text-sm text-muted">
                                {task.title} (#{task.id}): 알 수 없는 상태 ({task.statusId})
                            </li>
                        ))}
                    </ul>
                </div>
            )}
            <form onSubmit={addStatus}
                aria-label="상태 추가"
                className="grid min-w-0 gap-3 rounded-sm border border-border p-[var(--space-3)]">
                <h3 className="m-0 text-sm font-medium text-foreground">
                    새 상태 추가
                </h3>
                <div className="grid min-w-0 gap-3 @md:grid-cols-2">
                    <Input aria-label="새 상태 ID"
                        placeholder="stable-id"
                        value={newStatusId}
                        disabled={readOnly || savePendingState || !!removalDraft}
                        onChange={(event) => {
                            setNewStatusId(event.currentTarget.value);
                            setNewStatusError(null);
                        }} />
                    <Input aria-label="새 상태 이름"
                        placeholder="상태 이름"
                        value={newStatusName}
                        disabled={readOnly || savePendingState || !!removalDraft}
                        onChange={(event) => {
                            setNewStatusName(event.currentTarget.value);
                            setNewStatusError(null);
                        }} />
                    <NativeSelect aria-label="새 상태 분류"
                        value={newStatusCategory}
                        disabled={readOnly || savePendingState || !!removalDraft}
                        onChange={(event) => setNewStatusCategory(
                            event.currentTarget.value as WorkflowStatusCategory,
                        )}>
                        {statusCategories.map((category) => (
                            <option key={category.value} value={category.value}>
                                {category.label}
                            </option>
                        ))}
                    </NativeSelect>
                    <label className="grid min-w-0 gap-1 text-xs text-muted">
                        새 상태 색상
                        <Input aria-label="새 상태 색상"
                            type="color"
                            value={newStatusColor}
                            disabled={readOnly || savePendingState || !!removalDraft}
                            onChange={(event) => setNewStatusColor(
                                event.currentTarget.value,
                            )} />
                    </label>
                    <Button type="submit" variant="outline"
                        disabled={readOnly || savePendingState || !!removalDraft}>
                        상태 추가
                    </Button>
                </div>
                {newStatusError && (
                    <p role="alert" className="m-0 text-sm text-danger">
                        {newStatusError}
                    </p>
                )}
            </form>
            {saveError && (
                <p role="alert" className="m-0 text-sm text-danger">
                    {saveError}
                </p>
            )}
            {migrations.length > 0 && (
                <p role="status" className="m-0 text-xs text-muted">
                    저장 대기 중인 상태 이동 {migrations.length}건
                </p>
            )}
        </section>
    );
}

export { StatusWorkflowEditor };
export type {
    StatusWorkflowEditorProps,
    StatusWorkflowSaveRequest,
    WorkflowStatusCategory,
    WorkflowStatusDefinition,
    WorkflowStatusMigration,
    WorkflowTaskReference,
    WorkflowTaskStatusChange,
};
